cli-convert.calor:
§M{m001:Report:overflow=unchecked}
  §U{System}
  §U{System.Text}

  §NS{ns_global:_global:global}
    §CL{c001:Report:pub:stat}
      §MT{m002:Line:pub:stat} (str:item, f64:amount) -> str
        §R "${item,-8}|${amount,10:F2}"

      §MT{m003:Kind:pub:stat} (FormattableString:f) -> str
        §R (+ "fs:" f.Format)

      §MT{m004:Kind:pub:stat} (any:o) -> str
        §R (+ "object:" o)

      §MT{m005:Pick:pub:stat} (i32:x) -> str
        §R §C{Kind} (cast global::System.FormattableString "k=${x}")

      §MT{m006:Build:pub:stat} (i32:x) -> str
        §B{sb} (sb-new)
        §RAW
        sb.Append($"x={x}");
        §/RAW
        §R (sb-tostring sb)

